typedef struct Edge {
    int to, next;
} Edge;

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Edge *edges = (Edge *)malloc(sizeof(Edge) * 2 * (N - 1));
    int *head = (int *)malloc(sizeof(int) * (N + 1));
    int *deg = (int *)calloc(N + 1, sizeof(int));
    int *parent = (int *)calloc(N + 1, sizeof(int));
    int *dist = (int *)calloc(N + 1, sizeof(int));
    int *queue = (int *)malloc(sizeof(int) * (N + 5));

    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);

        edges[ecnt].to = b;
        edges[ecnt].next = head[a];
        head[a] = ecnt++;
        deg[a]++;

        edges[ecnt].to = a;
        edges[ecnt].next = head[b];
        head[b] = ecnt++;
        deg[b]++;
    }

    /* BFS from node 1 to get parent and distance */
    int front = 0, back = 0;
    queue[back++] = 1;
    parent[1] = -1;
    dist[1] = 0;

    while (front < back) {
        int v = queue[front++];
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            if (u == parent[v]) continue;
            parent[u] = v;
            dist[u] = dist[v] + 1;
            queue[back++] = u;
        }
    }

    /* Path length from 1 to N is dist[N].
       Fennec can secure nodes closer to 1, Snuke closer to N.
       Find the middle cut point on path 1..N. */
    int x = N;
    int steps = (dist[N] - 1) / 2;  /* move up from N to Snuke's side boundary */
    for (int i = 0; i < steps; i++) x = parent[x];
    int cutChild = x;          /* node on Snuke side adjacent to Fennec side */
    int cutParent = parent[x]; /* node on Fennec side */

    /* Count size of Fennec side by BFS/DFS avoiding crossing cutParent-cutChild */
    front = back = 0;
    queue[back++] = 1;
    int *vis = (int *)calloc(N + 1, sizeof(int));
    vis[1] = 1;
    int black = 0;

    while (front < back) {
        int v = queue[front++];
        black++;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            if ((v == cutParent && u == cutChild) || (v == cutChild && u == cutParent)) continue;
            if (!vis[u]) {
                vis[u] = 1;
                queue[back++] = u;
            }
        }
    }

    int white = N - black;

    if (black > white) {
        printf("Fennec\n");
    } else {
        printf("Snuke\n");
    }

    free(edges);
    free(head);
    free(deg);
    free(parent);
    free(dist);
    free(queue);
    free(vis);

    return 0;
}

