        }

        int[] distFromFennec = bfs(1, graph, N);
        int[] distFromSnuke = bfs(N, graph, N);

        int fennecCount = 0;
        int snukeCount = 0;

        for (int i = 1; i <= N; i++) {
            if (distFromFennec[i] <= distFromSnuke[i]) {
                fennecCount++;
            } else {
                snukeCount++;
            }
        }

        if (fennecCount > snukeCount) {
            System.out.println("Fennec");
        } else {
            System.out.println("Snuke");
        }
    }

    private static int[] bfs(int start, List<Integer>[] graph, int N) {
        int[] dist = new int[N + 1];
        Arrays.fill(dist, -1);
        Queue<Integer> queue = new LinkedList<>();
        dist[start] = 0;
        queue.offer(start);
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : graph[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    queue.offer(v);
                }
            }
        }
        return dist;
    }
}

