        adj = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < N - 1; i++) {
            int u = sc.nextInt(), v = sc.nextInt();
            adj[u].add(v); adj[v].add(u);
        }
        // Find path from 1 to N
        parent = new int[N + 1];
        Arrays.fill(parent, -1);
        Queue<Integer> q = new LinkedList<>();
        q.add(1); parent[1] = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) if (parent[v] == -1) { parent[v] = u; q.add(v); }
        }
        List<Integer> path = new ArrayList<>();
        for (int v = N; v != 0; v = parent[v]) path.add(v);
        Collections.reverse(path);
        int L = path.size() - 1;
        Set<Integer> pathSet = new HashSet<>(path);
        // Count subtree sizes for each path node
        long fennec = 0, snuke = 0;
        for (int i = 0; i <= L; i++) {
            long cnt = countSubtree(path.get(i), pathSet);
            if (i <= L / 2) fennec += cnt; else snuke += cnt;
        }
        System.out.println(fennec > snuke ? "Fennec" : "Snuke");
    }

    static long countSubtree(int root, Set<Integer> pathSet) {
        long cnt = 1;
        Queue<Integer> q = new LinkedList<>();
        q.add(root);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) if (!pathSet.contains(v) || v == root) {
                if (v != root) { pathSet.add(v); q.add(v); cnt++; }
            }
        }
        return cnt; // but we shouldn't modify pathSet!
    }
}

