    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        List<Integer>[] g = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < n - 1; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            g[a].add(b);
            g[b].add(a);
        }

        int[] parent = new int[n + 1];
        Arrays.fill(parent, -1);

        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(1);
        parent[1] = 0;

        while (!q.isEmpty()) {
            int v = q.poll();
            for (int to : g[v]) {
                if (parent[to] != -1) continue;
                parent[to] = v;
                q.add(to);
            }
        }

        List<Integer> path = new ArrayList<>();
        int cur = n;
        while (cur != 0) {
            path.add(cur);
            cur = parent[cur];
        }
        Collections.reverse(path);

        int m = path.size();
        int cutA = path.get((m - 1) / 2);
        int cutB = path.get(m / 2);

        boolean[] visited = new boolean[n + 1];
        int fennec = countReachable(g, cutA, cutB, visited);
        Arrays.fill(visited, false);
        int snuke = countReachable(g, cutB, cutA, visited);

        System.out.println(fennec > snuke ? "Fennec" : "Snuke");
    }

    static int countReachable(List<Integer>[] g, int start, int blocked, boolean[] visited) {
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(start);
        visited[start] = true;
        int count = 0;

        while (!q.isEmpty()) {
            int v = q.poll();
            count++;
            for (int to : g[v]) {
                if (to == blocked || visited[to]) continue;
                visited[to] = true;
                q.add(to);
            }
        }
        return count;
    }
}

